  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://esim.connectedyou.io/pages/affiliate-partner-program', 'official_program_page', 'commission_rate', 'The brand''s own affiliate page: ''You earn 20% or more for every customer you bring'', ''When someone purchases an eSIM using your link or coupon, you earn 20% commission. Get monthly payouts'', and in its FAQ: ''Earn 20% commission or more on all sales via your affiliate link. There''s no earning limit, and payments are made monthly.'' The fetched page explicitly states there is no earning limit, so commission_cap is UNCAPPED.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://esim.connectedyou.io/pages/affiliate-partner-program', 'official_program_page', 'creator_program', 'The same page recruits tech influencers, travel bloggers, content creators, eCommerce owners and hospitality partners, offers a free affiliate account with a unique referral link or QR code and real-time dashboard tracking, repeats ''there''s no commission limit'' in its maximisation answer, and publishes the affiliate support email esim@connectedyou.io. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 16, 18, 12, 9, 3, '{"niche_fit": "eSIM data is a core travel-creator staple - arrival, connectivity and travel-hack content for every destination audience.", "ugc_evidence": "The brand''s own page is creator-first: it names influencers, travel bloggers and content creators, and supplies referral links, QR codes for offline marketing and a real-time dashboard.", "compensation": "20% starting commission with monthly payouts, published on the brand''s own page, and the page explicitly states there is no earning limit - verified UNCAPPED.", "contact_access": "A direct affiliate support email (esim@connectedyou.io) is published on the program page itself - unusually accessible for a program this size.", "opportunity_availability": "Free affiliate account from the brand''s own page; sign-up is a simple partner registration.", "credibility": "A real operating eSIM storefront with a detailed program page, but a smaller, younger brand than the major travel names in the directory."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Cellesim', 'https://cellesim.com', 'Travel eSIM brand covering 190+ countries in 24 languages. Its own partner page pays 20% cash (not store credit) on every attributed sale with a 30-day first-touch cookie, a $50 payout threshold and NET-30 payment cycles via PayPal, Wise or bank transfer - and its FAQ states there is no cap on how much a partner can earn.', null, 'published') returning id into bid;
