  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://cellesim.com/en/partners', 'official_program_page', 'creator_program', 'The same page says it is ''Trusted by travel creators, bloggers and newsletters in 190+ countries'', that most creators are approved within a couple of days with no traffic minimums, and that audience size does not matter (''we care more about relevance and trust''). That is eligibility evidence, not a creator count, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 16, 18, 8, 9, 3, '{"niche_fit": "eSIMs for 190+ countries fit any travel creator''s toolkit - destination guides, packing lists and arrival tips.", "ugc_evidence": "The partner page is built for creators: personal short links, deep links to country pages, a live dashboard and explicit ''no big audience needed'' language.", "compensation": "20% cash on every sale with a 30-day cookie, published on the brand''s own page, and the FAQ explicitly states there is no cap on earnings - verified UNCAPPED.", "contact_access": "Application runs through the brand''s own partner page; no direct partnerships email is published on it.", "opportunity_availability": "Open application with no traffic minimums and a stated couple-of-days approval.", "credibility": "A real, operating eSIM storefront with unusually transparent payout terms, but a young brand with a short track record."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Simsima', 'https://simsima.io', 'Travel eSIM brand whose own affiliate page pays a flat 12% commission on every attributed sale, tracked by link or promo code. The program is free with no minimum audience size, accepts applications via a social profile, and its FAQ states there is no cap on how much an affiliate can earn.', null, 'published') returning id into bid;
