  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://simsima.io/en/affiliate-program', 'official_program_page', 'creator_program', 'The same page: ''Free to join, with no minimum audience size required'', ''you can apply with your social profile'', and it names content creators, bloggers, YouTubers and Instagram/TikTok creators as ideal partners. Commissions are confirmed after the refund window and paid on request from the dashboard. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 15, 15, 8, 9, 3, '{"niche_fit": "A simple, honest eSIM offer that travel creators can recommend in any destination content.", "ugc_evidence": "The program page explicitly recruits social creators and lets them apply with a social profile instead of a website - genuinely creator-facing mechanics.", "compensation": "12% on every sale, published on the brand''s own page, with an FAQ that explicitly states there is no cap on earnings - verified UNCAPPED.", "contact_access": "Application runs through the brand''s own page; no direct partnerships email is published on it.", "opportunity_availability": "Free to join, no minimum audience, no website required - among the lowest-friction applications in this round.", "credibility": "A real operating eSIM storefront with clear published conditions, but a small, young brand."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('SimFuse', 'https://simfuse.app', 'Travel eSIM app and store covering 209 destinations, sold with per-GB pricing in 18 languages. Its own partner page starts affiliates at 10% of the cash value of every sale - including renewals and top-ups - pays on activation (or at day 90 at the latest), and its FAQ states there is no cap on how much you can earn in a month.', null, 'published') returning id into bid;
