  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://simfuse.app/affiliates/', 'official_program_page', 'creator_program', 'The same page is ''Built for people with a travel audience'' - creators and bloggers, comparison sites, tour operators and communities - with ''no minimum amount of traffic'', human-reviewed applications, a live dashboard, deep links and a partner API. Renewals and top-ups also earn. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 15, 14, 8, 8, 3, '{"niche_fit": "eSIMs across 209 destinations with honest per-GB pricing - an easy, credible recommendation for travel audiences.", "ugc_evidence": "A creator-built partner page: dashboard, deep links to specific plans, a partner API and explicit no-minimum-traffic language.", "compensation": "10% starting rate on the full cash value, renewals included, published on the brand''s own page, with an FAQ explicitly stating no cap on monthly earnings - verified UNCAPPED; higher rates are by conversation after proven volume.", "contact_access": "Application runs through the brand''s own page; no direct partnerships email is published on it.", "opportunity_availability": "Open application, human-reviewed for genuine traffic rather than size.", "credibility": "A real operating eSIM product with exceptionally transparent published terms, but a young brand."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Kaya Movement', 'https://www.kayamovement.com', 'Sustainable activewear and movement-apparel brand running a hands-on ambassador program through UpPromote. Its own ambassadors page publishes a 20% commission on every sale made through an ambassador''s link or coupon, a 90-day link window, free merchandise to create with, and twice-monthly payouts - with a published contact email for questions.', null, 'published') returning id into bid;
