  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.kayamovement.com/pages/ambassadors', 'official_program_page', 'commission_rate', 'The brand''s own ambassadors page: ''You get free merchandise, 20% commission for every sale made through your referral link and coupon and 30% lifetime discount to shop in our store'', ''An Ambassador link is limited to 90 Calendar Days per customer'', and ''Get paid on 14th & 28th of every month via Paypal or Bank Transfer'', tracked on an UpPromote dashboard (af.uppromote.com). No cap statement appears on the page, so commission_cap stays unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.kayamovement.com/pages/ambassadors', 'official_program_page', 'creator_program', 'The same page sets the creator mechanics: ambassadors are chosen for brand fit, must create a minimum of 2 images and a 15-second reel with the products within 2 weeks, gift followers 15% off, and join on a 6-month trial. It publishes the contact email contact@kayamovement.com for program questions. No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 17, 16, 12, 6, 3, '{"niche_fit": "Sustainable activewear with a strong visual identity is prime fitness and yoga UGC - movement demos, outfit content and wellness routines.", "ugc_evidence": "A true creator program, not a bare affiliate link: free merchandise to film with, defined content deliverables, a personalised coupon, a live dashboard and marketing tools library.", "compensation": "20% on every sale through link or coupon with a 90-day window and twice-monthly payouts, published on the brand''s own page; no cap statement was found, so the cap is honestly unknown.", "contact_access": "The program page publishes a direct email (contact@kayamovement.com) for ambassador questions.", "opportunity_availability": "Selective rather than open: ambassadors are ''specially chosen'' for brand fit and start on a 6-month trial, which limits availability.", "credibility": "A real, operating DTC activewear brand with detailed published program terms, but small and niche."}'::jsonb);
