  insert into public.brands (name, website, description, country, status) values ('Woolly Clothing', 'https://www.woolly.clothing', 'Seattle-born merino wool basics brand (founded 2013) making underwear, basics, athleisure and lifestyle pieces from 95-100% merino under a ''More Wool, Less Plastic'' mantra. Its Awin merchant profile publishes a 15% commission on sales made through an affiliate link, a 7-day attribution window, a $100+ average order value and free products for affiliates.', 'United States', 'published') returning id into bid;
