  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 13, 16, 8, 8, 3, '{"niche_fit": "Merino basics and underwear are natural everyday-fashion, travel-packing and comfort-content staples - one-bag travel and capsule wardrobe videos especially.", "ugc_evidence": "An official Awin programme with free products for affiliates and a $100+ AOV story; publisher-oriented, but the free-product mechanic suits UGC creators.", "compensation": "15% on sales through the affiliate link, published on the brand''s own Awin merchant profile - a strong rate for apparel; the 7-day cookie is short, and no cap statement was found, so the cap is honestly unknown.", "contact_access": "Contact runs through the Awin programme; no direct partnerships email is published on the profile.", "opportunity_availability": "Open application through the Awin merchant profile, approval-based.", "credibility": "A Seattle DTC brand operating since 2013 with national press coverage of its collections - established, if still niche."}'::jsonb);
