  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Sakara Circle Ambassador Program', 'https://www.sakara.com/pages/ambassadors', 'https://www.sakara.com/pages/ambassadors', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.sakara.com/pages/ambassadors', 'brand_website', 'affiliate_program', 'Sakara''s own ambassadors page (the Sakara Circle program), fetched first-hand, states: ''For each new client referral, you''ll receive a commission (total earnings for which are unlimited), and paid out monthly''; members receive a unique code and link, and referrals get 20% off their first purchase. The explicit statement that total earnings are unlimited is an earnings-cap statement, so commission_cap is recorded as uncapped. The page publishes no commission percentage, so commission_rate is null. The program is a curated community of wellness experts and publishes no creator-count data, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 13, 7, 8, 5, '{"compensation": "Earnings are explicitly unlimited on the brand''s own page, but no commission percentage is published, so no rate can be recorded.", "contact_access": "Application runs through the brand''s own ambassadors page; no public partnerships email was published on the fetched page.", "credibility": "A well-known premium US wellness brand with national meal-delivery distribution and a long operating history.", "niche_fit": "Plant-based meals, cleanses and wellness products are highly demonstrable staples for food, health and wellness-routine creators.", "opportunity_availability": "Program is live from the brand page, but membership is a curated community, so entry is application-based rather than instant.", "ugc_evidence": "A named ambassador program (Sakara Circle) with unique codes and links built for a community of wellness creators and experts."}'::jsonb);
