  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://mitoredlight.com/pages/affiliate-program-agreement', 'brand_website', 'affiliate_program', 'Mito Red Light''s own affiliate program agreement, fetched first-hand, publishes 10% commission on devices and 20% on skincare (the 10% base device rate is recorded), a 7-day cookie, a $200 minimum payout requiring at least two sales (one not a self-purchase), monthly payouts via PayPal or ACH, a dashboard via Social Snowball, and eligibility that explicitly includes content creators (UGC and influencers); applications run through the brand''s community page, and the site publishes the contact email info@mitoredlight.com. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 16, 8, 9, 4, '{"compensation": "Published rates in the brand''s own agreement: 10% on devices and 20% on skincare, paid monthly; the $200 minimum payout and 7-day cookie temper the headline rate.", "contact_access": "A published brand contact email plus an application route through the brand''s community page.", "credibility": "An established specialist red-light therapy brand with a published legal agreement for its program.", "niche_fit": "Red-light therapy devices are visual, routine-based products that fit biohacking, recovery, skincare and wellness creators.", "opportunity_availability": "Program is live and open to apply now through the brand''s community page.", "ugc_evidence": "The agreement explicitly names content creators (UGC and influencers) as eligible affiliates."}'::jsonb);
