  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'BistroMD Affiliate Program', 'https://www.bistromd.com/pages/affiliate', 'https://www.bistromd.com/pages/affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.bistromd.com/pages/affiliate', 'brand_website', 'affiliate_program', 'BistroMD''s own affiliate program page, fetched first-hand, invites partners to ''earn commissions by promoting bistroMD products'' and names diet review websites, fitness and wellness websites, bloggers, content creators and influencers as ideal partners, with the join route running through Impact. The brand page publishes no payout figure; third-party sources attribute a flat $20 per sale to the program (LinkClicky, March 2024; LinkWhisper, describing the brand''s landing page), while Lasso reports $36 per sale, so the payout is a flat bounty with conflicting reports and commission_rate is null with the conflict documented here. No earnings-cap statement is published, so commission_cap is unknown; no creator-count data is published, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 13, 11, 6, 9, 5, '{"compensation": "Third parties attribute a flat $20-per-sale bounty to the program via Impact, but Lasso reports $36, so no figure is recorded as the rate; flat pay on a high-ticket meal plan is still meaningful.", "contact_access": "Application runs from the brand''s own affiliate page into Impact; no public partnerships email was published on the fetched page.", "credibility": "A long-running, doctor-designed meal-delivery brand and one of the best-known names in weight-loss meal delivery.", "niche_fit": "Doctor-designed weight-loss meals are a natural fit for weight-loss, nutrition, fitness and wellness creators.", "opportunity_availability": "Program is live and described by the brand as quickly expanding, with joining open now.", "ugc_evidence": "The brand page explicitly recruits bloggers, content creators and influencers, and third parties report creative assets for partners."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('MAONO', 'https://www.maono.com', 'Microphone and audio-gear brand aimed at streamers, podcasters and creators — USB and XLR microphones, audio interfaces, mixers and headphones — sold through maono.com. Its own affiliate program page publishes 5%-20% commission on every successful referral, a 30-day cookie, monthly payments and dedicated partner support.', 'China', 'published') returning id into bid;
