  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.maono.com/pages/affiliate-program', 'official_site', 'affiliate', 'MAONO''s own affiliate program page fetched in full: ''Earn 5%-20% commission on every successful referral'', a 30-day cookie window, monthly payments and dedicated partner support for partners. The recorded 5% is the floor of the range the brand itself publishes. The page names no network — application is through maono.com. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 12, 9, 8, 4, '{"compensation": "The brand publishes a wide 5%-20% range; the recorded floor is fair for budget audio gear, but where a creator lands in the range is not published, and no cap statement exists", "contact_access": "Direct application on the brand''s own program page; no affiliate email is published", "credibility": "An established creator-audio brand sold globally through its own store and major retailers", "niche_fit": "Microphones and audio interfaces are core creator gear \u2014 mic tests, podcast setups and streaming-room tours are natural UGC for this brand", "opportunity_availability": "Open application through the brand''s own page, subject to approval", "ugc_evidence": "A brand-published affiliate program on the brand''s own page with dedicated partner support; aimed at referral partners generally rather than a named creator tier"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Hollyland', 'https://store.hollyland.com', 'Wireless video and audio brand for filmmakers and creators — wireless microphones, video transmission systems, intercoms and cameras — sold through store.hollyland.com. Its own affiliate program page publishes 5% commission on video solutions, intercoms and cameras and 8% on wireless microphones, a 45-day cookie and average order values over $500, and explicitly invites content creators, influencers and bloggers.', 'China', 'published') returning id into bid;
