  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://store.hollyland.com/pages/hollyland-affiliate-program', 'official_site', 'affiliate', 'Hollyland''s own affiliate program page fetched in full: 5% commission for video solutions, intercom systems and cameras and 8% for wireless microphones, a 45-day cookie, average order value over $500, monthly payouts via PayPal or bank transfer, the published contact affiliate@hollyland.com, and an explicit invitation to content creators, influencers and bloggers. The recorded 5% is the floor of the brand''s published category rates. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'verified', now());
