  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.obsbot.com/affiliate-program', 'official_site', 'affiliate', 'OBSBOT''s own affiliate program page fetched in full: 8%-10% commissions, a 30-day cookie, free to join with no minimum sales quota, monthly payment through ShareASale, joining routes via ShareASale (Merchant ID 53691) or Awin (Merchant ID 79596), and the published contact affiliate@obsbot.com. The recorded 8% is the floor of the brand-published range, and the network recorded is ShareASale, the route the page ties to payment. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'verified', now());
