  insert into public.brands (name, website, description, country, status) values ('Edifier', 'https://ca.edifier.com', 'Global audio company — powered speakers, bookshelf speakers, headphones and earbuds — sold through regional stores including ca.edifier.com. Its Canadian PR page routes partnership and affiliate applications to the Edifier Affiliate portal, and a comparison of the brand''s official regional and network pages shows 10% commission on both its Awin profile and its Canadian UpPromote page, with a 7% US route on MyLead.', 'China', 'published') returning id into bid;
