  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Edifier Affiliate Program — official Awin profile and Canadian portal both publish 10% commission (7% US route on MyLead); apply via the brand''s PR page', 'https://ca.edifier.com/pages/pr-contact', 'https://ca.edifier.com/pages/pr-contact', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ca.edifier.com/pages/pr-contact', 'official_site', 'affiliate', 'Edifier''s own Canadian PR contact page fetched: ''Up for a partnership and scoring commissions? No need to hold back — get in touch or tap into Edifier Affiliate to apply straight off the bat!'', with the application link leading to the brand''s UpPromote affiliate portal (af.uppromote.com). The page publishes no email address and no rate itself; the rates come from the official network profiles compared in the next item.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.sharehub.fun/brands/audio/edifier/', 'listing', 'affiliate', 'ShareHub''s Edifier directory entry (checked 30 October 2026) compares the brand''s official regional and network pages: ''The brand''s Canadian UpPromote page and its Awin network profile advertise a 10% commission rate, while the MyLead platform lists a 7% commission for the US program'', for a program the entry describes as published for creators and publishers, with no minimum follower counts mentioned on the official pages checked. The recorded 10% is the rate two official routes agree on, and the network recorded is Awin. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 14, 9, 7, 5, '{"compensation": "10% is agreed by two official routes (the Awin profile and the Canadian UpPromote page) \u2014 solid, transparent pay; a US route on MyLead pays 7%, and no cap statement exists", "contact_access": "Application runs through the brand''s own PR page into its affiliate portal; no affiliate email is published on the fetched page", "credibility": "One of the world''s largest speaker and headphone makers, with documented programs across multiple networks and regions", "niche_fit": "Speakers and headphones are proven audio-UGC categories \u2014 listening tests, desk-audio setups and budget roundups are natural content", "opportunity_availability": "Open application through the network and portal routes, subject to approval; terms differ by region", "ugc_evidence": "The brand''s own PR page recruits partnerships, and a directory comparison of official pages describes the program as published for creators and publishers; no dedicated creator tier is published"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Fifine', 'https://fifinemicrophone.com', 'Budget audio brand for streamers and podcasters — USB and XLR microphones, mic arms and audio accessories — sold through fifinemicrophone.com. Its own Social Media Partnership page recruits creators by content topic, promising free and latest products plus ''bonuses such as affiliate commissions'', and publishes named partnership reps with direct emails for gaming/streaming, podcasting, video production, unboxing and setup content.', 'China', 'published') returning id into bid;
