  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'FIFINE Social Media Partnership — brand''s own page recruits creators by content topic with affiliate commissions and publishes named rep emails; no commission rate published', 'https://fifinemicrophone.com/pages/fifine-marketing-staff-list', 'https://fifinemicrophone.com/pages/fifine-marketing-staff-list', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://fifinemicrophone.com/pages/fifine-marketing-staff-list', 'official_site', 'affiliate', 'FIFINE''s own Social Media Partnership page fetched in full: ''Join FIFINE, become a partner!... It''s not just about free and the latest product, but also bonuses such as affiliate commissions and giveaway gifts to your fans!'', with authenticated reps listed by YouTube content topic — Gaming/Streaming: Iris, fifineiris@gmail.com; Podcasting/Voice-over/Audio: Bruce, fifinebrucetherep@gmail.com; Video Production/Photography: Ted, tedfifine@gmail.com; Unboxing: Darren, fifinemarketingrepdarren@gmail.com; Setup/Room Tour: Joyce, joycechowfifine@gmail.com — and the official support channel web@fifine.cc for verifying reps. The page publishes no commission rate, so commission_rate is null rather than guessed from third-party ceiling claims. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 6, 13, 7, 4, '{"compensation": "Affiliate commissions are promised on the brand''s own page but no rate is published anywhere on it, so compensation cannot be scored on a number; no cap statement exists", "contact_access": "Named partnership reps with direct emails for five content topics, plus the official support email (web@fifine.cc) \u2014 the strongest contact access in this batch", "credibility": "A widely sold budget-audio brand with a long-standing creator-partnership operation and a published rep-authentication list", "niche_fit": "Budget streaming and podcast microphones are among the most-reviewed products in creator UGC \u2014 mic shootouts and starter-studio setups are natural content", "opportunity_availability": "Partnership starts by contacting a rep for your topic; acceptance is at the brand''s discretion", "ugc_evidence": "A dedicated Social Media Partnership page that recruits creators by content topic and names individual partnership reps \u2014 direct, unambiguous creator evidence"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Owlet', 'https://owletcare.com', 'Smart baby-monitor company — the Dream Sock and Dream Duo track heart rate and average oxygen level as sleep quality indicators — sold through owletcare.com. Its own affiliate program page offers ''up to 15% commission'' with exclusive rates for Premium Publishers and gifted product for coverage, but publishes no standard rate, and directories disagree on what the program pays.', 'United States', 'published') returning id into bid;
