  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Owlet Affiliate Program — brand page advertises up to 15% commission with exclusive Premium Publisher rates, but publishes no standard rate and directories conflict (3% vs 9%); recruitment via Awin', 'https://owletcare.com/pages/affiliate-program', 'https://owletcare.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://owletcare.com/pages/affiliate-program', 'official_site', 'affiliate', 'Owlet''s own affiliate program page fetched: ''Join our affiliate program to drive awareness and excitement about Owlet''s award-winning technology, including the Dream Sock and Dream Duo — the only baby monitor to track heart rate and average oxygen level as Sleep Quality Indicators'', with benefits ''Earn up to 15% commission on orders placed on our website'' and ''Exclusive commission rates and opportunities for Premium Publishers'', plus gifted product for coverage. ''Up to 15%'' is a ceiling, not a standard rate, and the page names no network.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/owlet/', 'listing', 'affiliate', 'Rate-conflict note: Lasso''s Owlet program page reports 3% per sale with a 15-day cookie, while Lasso''s separate Owlet Baby Care Inc. page reports 9% per sale — two conflicting figures from the same directory, neither matching a brand-published standard rate. Because the brand publishes only an ''up to 15%'' ceiling and directories conflict, commission_rate is null with the conflict documented here. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.getaff.org/en/programs/owletbabycare-co-uk', 'listing', 'affiliate', 'Route note: GetAff''s network-catalogue entry (synced from Awin) states ''Owlet recruits affiliates through Awin'' for the US market and that the commission rate is not published in the public catalogue — the basis for recording Awin as the network; the brand''s own page remains the application route.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 13, 7, 9, 7, 4, '{"compensation": "Only an ''up to 15%'' ceiling is brand-published and directories conflict (3% vs 9%), so compensation is scored on unsettled evidence; no cap statement exists", "contact_access": "Application through the brand''s own page into Awin; no affiliate email is published", "credibility": "A well-known US baby-tech brand whose Dream Sock is a category-defining product sold nationally", "niche_fit": "Smart baby monitors are a focused parenting-tech niche \u2014 newborn must-haves, sleep-training and nursery-tour content are natural fits, though narrower than general tech", "opportunity_availability": "Open application, subject to approval; exclusive rates are reserved for Premium Publishers", "ugc_evidence": "A brand-published affiliate page courting publishers with gifted product for coverage and premium-publisher rates; creator-facing, though framed around publishers"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('SIHOO', 'https://uk.sihoo.com', 'Ergonomic furniture brand founded in 2011 — office chairs and sit-stand desks — sold through regional stores including uk.sihoo.com. Its own affiliate program page publishes 2%-8% commission on order value with a 30-day window, joining through Impact (or GoAffPro), monthly payouts, and a dedicated track for content creators and influencers.', 'China', 'published') returning id into bid;
