  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'SIHOO Affiliate Program — brand''s own page publishes 2%-8% commission on order value via Impact, 30-day window, monthly payouts', 'https://uk.sihoo.com/pages/affiliate-program', 'https://uk.sihoo.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uk.sihoo.com/pages/affiliate-program', 'official_site', 'affiliate', 'SIHOO''s own UK affiliate page fetched in full: ''When someone clicks your link and makes a purchase within 30 days, you''ll earn a 2%-8% commission on the order value'', ''We offer between 2% and 8% commission, with higher tiers available for exceptional partners'', joining by creating an Impact publisher account (a GoAffPro route is also offered), no registration fees for either programme, monthly payouts on both routes, and a dedicated section ''For content creators & influencers''. The recorded 2% is the floor of the brand-published range. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 14, 9, 9, 8, 4, '{"compensation": "The published range starts at a low 2% floor and reaches 8%, with higher tiers for exceptional partners; where a creator lands is not published, and no cap statement exists", "contact_access": "Application runs through the brand''s own page into Impact; no affiliate email is published", "credibility": "Designing ergonomic furniture since 2011, with regional stores and a complete, terms-bearing program page", "niche_fit": "Ergonomic chairs are a desk-setup and home-office UGC staple \u2014 chair reviews, posture content and workspace tours are natural fits", "opportunity_availability": "Open application through Impact with review promised within 1-2 working days, and no joining fees", "ugc_evidence": "The brand''s own page carries a dedicated ''For content creators & influencers'' track alongside reviewer, media and deal-site tracks \u2014 direct creator evidence"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('FlexiSpot', 'https://flexispot.com', 'Standing-desk and ergonomic furniture brand — electric sit-stand desks, desk chairs and workspace accessories — sold through flexispot.com. Its affiliate program runs primarily on ShareASale in the US (with CJ and a direct portal also reported), where new affiliates start at a 5% base commission and high-volume performers can negotiate up to 10%.', 'United States', 'published') returning id into bid;
