  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'FlexiSpot Affiliate Program — directories report a 5% base commission on ShareASale (up to 10% negotiated), 30-day cookie, $50 minimum payout', 'https://affiliateprogramsguru.com/programs/flexispot/', 'https://affiliateprogramsguru.com/programs/flexispot/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliateprogramsguru.com/programs/flexispot/', 'listing', 'affiliate', 'AffiliateProgramsGuru''s FlexiSpot program profile (last verified April 2026) reports 5%-10% commission (CPS): ''New affiliates start at the 5% base rate, while high-volume performers can negotiate rates up to 10%'', with ShareASale ''the primary platform for US-based affiliates'', CJ Affiliate and a direct portal on FlexiSpot''s own website also offered, a 30-day cookie, a $50 minimum payout and Net 20 payment terms. The recorded 5% is that corroborated base rate. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/flexispot/', 'listing', 'affiliate', 'Dissenting-figure note: LinkClicky''s older CJ listing (updated March 2024) records 3% per sale, and AffiliateMarketingGirl reports a 5%-15% tiered range — figures that bracket the recorded 5% base from below and above; the best-corroborated current base rate on the primary ShareASale route governs this entry.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 11, 8, 7, 4, '{"compensation": "A 5% base corroborated by the freshest directory verification, rising to 10% negotiated \u2014 fair on high-ticket desks; older and higher conflicting figures exist and no cap statement is published", "contact_access": "Application through ShareASale; no brand affiliate page or email was verified for this entry", "credibility": "One of the largest standing-desk brands in the US market, with programs documented across several networks", "niche_fit": "Standing desks are a cornerstone of desk-setup UGC \u2014 workspace tours, WFH upgrades and desk-build content are natural fits", "opportunity_availability": "Open application through ShareASale (US-primary), subject to approval", "ugc_evidence": "The program is documented across directories as open to reviewers and publishers, but no brand creator page was fetched, so creator evidence is directory-level rather than brand-published"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('UPLIFT Desk', 'https://www.upliftdesk.com', 'Premium standing-desk company — height-adjustable desks, chairs and workspace accessories — sold through upliftdesk.com. Its own Affiliate & Influencers page runs two tracks, one for publishers, reviewers and bloggers and one for creators, publishing a 30-day cookie, complimentary or discounted products for eligible partners and a dedicated affiliate manager — but no commission rate.', 'United States', 'published') returning id into bid;
