  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.upliftdesk.com/affiliate/', 'official_site', 'affiliate', 'UPLIFT Desk''s own Affiliate & Influencers page fetched in full: ''Join the UPLIFT Desk affiliate & influencer program... earn commission when your recommendation leads to a purchase'', separate tracks for ''publishers, reviewers, bloggers'' and for creators who ''bring their workspaces and routines to life through social media content, video, and storytelling'', a 30-day cookie window, ''high average order values mean bigger payouts per sales'', complimentary or discounted products for eligible partners, a dedicated affiliate manager, and the published contact hello@upliftdesk.com. The page publishes no commission rate, so commission_rate is null rather than guessed. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'verified', now());
