  insert into public.brands (name, website, description, country, status) values ('PetPlate', 'https://www.petplate.com', 'Fresh dog-food subscription company — human-grade, vet-designed meal plans delivered to subscribers — sold through petplate.com. Its program terms on Awin confirm a live affiliate program whose allowed partner types explicitly include content creators and influencers and communities and UGC, while directories report the pay as a flat bounty per new client rather than a percentage.', 'United States', 'published') returning id into bid;
