  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'PetPlate Affiliate Program — live on Awin with content creators and UGC communities explicitly allowed; pay reported as a flat bounty per new client ($50 on the brand''s ambassador page), amount unsettled across sources', 'https://ui.awin.com/advertiser-terms/70899?setLocale=en_GB', 'https://ui.awin.com/advertiser-terms/70899?setLocale=en_GB', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/advertiser-terms/70899?setLocale=en_GB', 'listing', 'affiliate', 'PetPlate''s Awin program terms fetched in full (last updated 05 Aug 2025): the terms confirm a live program, list allowed partner types including ''Content creators and influencers'', ''Communities and UGC'', ''Social traffic'' and ''Editorial content'', and set out commission validation rules (no product categories excluded; commission declined for non-new customers among other reasons). The terms publish no commission rate or bounty amount.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.findaffiliates.online/blog/pet-affiliate-programs-for-creators-2026', 'listing', 'affiliate', 'FindAffiliates'' creator-focused comparison reports that ''the PetPlate ambassador page confirms a $50 commission for each new client referral and says commissions are paid monthly'' — a flat per-client bounty structure rather than a percentage rate.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://articlesbase.com/business/marketing-and-advertising/affiliate-marketing/petplate-affiliate-program-review-2024-benefits-payments-and-more/', 'listing', 'affiliate', 'Amount-conflict note: other directories report different flat amounts from different eras — a $25 flat fee per sale in one long-running listing, and a by-plan table of $25 per weekly, $50 per monthly and $100 per quarterly subscription in a 2024 review — while percentage claims elsewhere (15%, 25%-50%) conflict with the flat-bounty structure the brand''s own ambassador page is reported to publish. Because the pay is a flat bounty whose amount is unsettled across sources, commission_rate is null with the structure documented here. No earnings-cap statement is published, so the cap is unknown, and no creator count is published, so saturation stays unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 14, 8, 8, 7, 4, '{"compensation": "Pay is a flat bounty per new client rather than a percentage; $50 is reported from the brand''s own ambassador page but other sources report $25-$100 by plan or era, so the amount is unsettled and no cap statement exists", "contact_access": "Application through Awin; no affiliate email is published on the pages fetched", "credibility": "An established US fresh-pet-food subscription brand with current, complete program terms on Awin", "niche_fit": "Fresh dog food is a proven pet-owner content category \u2014 meal reveals, picky-eater trials and coat and energy updates are natural UGC", "opportunity_availability": "Open application through Awin, subject to the program''s terms and approval", "ugc_evidence": "The program''s own Awin terms explicitly allow content creators and influencers and communities and UGC as partner types, and the brand runs an ambassador page \u2014 direct creator evidence"}'::jsonb);
